CREATE TABLE IF NOT EXISTS users (id VARCHAR(36) PRIMARY KEY, employee_code VARCHAR(50), name VARCHAR(200) NOT NULL, email VARCHAR(200) UNIQUE NOT NULL, password_hash TEXT NOT NULL, role VARCHAR(30) DEFAULT 'viewer', department VARCHAR(100), phone VARCHAR(20), is_active TINYINT(1) DEFAULT 1, last_login DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS refresh_tokens (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36), token TEXT NOT NULL, expires_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS company_settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS role_permissions (id INT AUTO_INCREMENT PRIMARY KEY, role VARCHAR(50), module_key VARCHAR(50), can_view TINYINT(1) DEFAULT 0, can_create TINYINT(1) DEFAULT 0, can_edit TINYINT(1) DEFAULT 0, can_delete TINYINT(1) DEFAULT 0, can_approve TINYINT(1) DEFAULT 0, can_export TINYINT(1) DEFAULT 0, UNIQUE KEY role_module(role,module_key));
CREATE TABLE IF NOT EXISTS uom_master (id INT AUTO_INCREMENT PRIMARY KEY, uom_code VARCHAR(20) UNIQUE, uom_name VARCHAR(100), is_active TINYINT(1) DEFAULT 1);
CREATE TABLE IF NOT EXISTS hsn_master (id INT AUTO_INCREMENT PRIMARY KEY, hsn_code VARCHAR(10), description VARCHAR(255), gst_rate DECIMAL(5,2));
CREATE TABLE IF NOT EXISTS item_master (id VARCHAR(36) PRIMARY KEY, item_code VARCHAR(50) UNIQUE NOT NULL, item_name VARCHAR(200) NOT NULL, category VARCHAR(30), uom_id INT, hsn_code VARCHAR(10), gst_rate DECIMAL(5,2) DEFAULT 18, reorder_level DECIMAL(10,3) DEFAULT 0, reorder_qty DECIMAL(10,3) DEFAULT 0, standard_cost DECIMAL(12,2) DEFAULT 0, description TEXT, is_active TINYINT(1) DEFAULT 1, created_by VARCHAR(36), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers (id VARCHAR(36) PRIMARY KEY, customer_code VARCHAR(50) UNIQUE, company_name VARCHAR(200) NOT NULL, contact_person VARCHAR(200), phone VARCHAR(20), email VARCHAR(200), gstin VARCHAR(15), state VARCHAR(100), address TEXT, payment_terms INT DEFAULT 30, is_active TINYINT(1) DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vendors (id VARCHAR(36) PRIMARY KEY, vendor_code VARCHAR(50) UNIQUE, company_name VARCHAR(200) NOT NULL, contact_person VARCHAR(200), phone VARCHAR(20), email VARCHAR(200), gstin VARCHAR(15), state VARCHAR(100), address TEXT, payment_terms INT DEFAULT 30, vendor_type VARCHAR(30) DEFAULT 'material', is_active TINYINT(1) DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS warehouses (id VARCHAR(36) PRIMARY KEY, warehouse_code VARCHAR(50) UNIQUE, warehouse_name VARCHAR(200), address TEXT, is_default TINYINT(1) DEFAULT 0, is_active TINYINT(1) DEFAULT 1);
CREATE TABLE IF NOT EXISTS departments (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) UNIQUE, is_active TINYINT(1) DEFAULT 1);
CREATE TABLE IF NOT EXISTS machines (id VARCHAR(36) PRIMARY KEY, machine_code VARCHAR(50) UNIQUE, machine_name VARCHAR(200), department_id INT, is_active TINYINT(1) DEFAULT 1);
CREATE TABLE IF NOT EXISTS stock_ledger (id VARCHAR(36) PRIMARY KEY, item_id VARCHAR(36) NOT NULL, warehouse_id VARCHAR(36), transaction_type VARCHAR(40) NOT NULL, reference_type VARCHAR(50), reference_id VARCHAR(36), qty_in DECIMAL(10,3) DEFAULT 0, qty_out DECIMAL(10,3) DEFAULT 0, balance_qty DECIMAL(10,3) DEFAULT 0, rate DECIMAL(12,2) DEFAULT 0, amount DECIMAL(12,2) DEFAULT 0, notes TEXT, created_by VARCHAR(36), transaction_date DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stock_summary (item_id VARCHAR(36), warehouse_id VARCHAR(36), current_qty DECIMAL(10,3) DEFAULT 0, avg_rate DECIMAL(12,2) DEFAULT 0, total_value DECIMAL(14,2) DEFAULT 0, last_updated DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(item_id,warehouse_id));
CREATE TABLE IF NOT EXISTS notifications (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36), severity VARCHAR(20) DEFAULT 'info', title VARCHAR(200) NOT NULL, description TEXT, is_read TINYINT(1) DEFAULT 0, read_at DATETIME, source VARCHAR(30), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activity_log (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36), module VARCHAR(50), action VARCHAR(100), reference_type VARCHAR(50), reference_id VARCHAR(36), changes JSON, ip_address VARCHAR(45), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchase_requisitions (id VARCHAR(36) PRIMARY KEY, pr_number VARCHAR(50) UNIQUE, requested_by VARCHAR(36), status VARCHAR(30) DEFAULT 'pending', notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchase_orders (id VARCHAR(36) PRIMARY KEY, po_number VARCHAR(50) UNIQUE, vendor_id VARCHAR(36), status VARCHAR(30) DEFAULT 'draft', total_amount DECIMAL(12,2) DEFAULT 0, created_by VARCHAR(36), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS grn (id VARCHAR(36) PRIMARY KEY, grn_number VARCHAR(50) UNIQUE, po_id VARCHAR(36), vendor_id VARCHAR(36), status VARCHAR(30) DEFAULT 'draft', received_date DATE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bom (id VARCHAR(36) PRIMARY KEY, bom_code VARCHAR(50) UNIQUE, finished_item_id VARCHAR(36), output_qty DECIMAL(10,3) DEFAULT 1, is_active TINYINT(1) DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS work_orders (id VARCHAR(36) PRIMARY KEY, wo_number VARCHAR(50) UNIQUE, finished_item_id VARCHAR(36), bom_id VARCHAR(36), planned_qty DECIMAL(10,3), produced_qty DECIMAL(10,3) DEFAULT 0, status VARCHAR(30) DEFAULT 'draft', created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS job_work_orders (id VARCHAR(36) PRIMARY KEY, jw_number VARCHAR(50) UNIQUE, vendor_id VARCHAR(36), process_name VARCHAR(200), status VARCHAR(30) DEFAULT 'sent', expected_return_date DATE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS qc_inspections (id VARCHAR(36) PRIMARY KEY, inspection_type VARCHAR(30), reference_id VARCHAR(36), item_id VARCHAR(36), inspected_qty DECIMAL(10,3), accepted_qty DECIMAL(10,3), rejected_qty DECIMAL(10,3) DEFAULT 0, overall_result VARCHAR(20), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quotations (id VARCHAR(36) PRIMARY KEY, quotation_number VARCHAR(50) UNIQUE, customer_id VARCHAR(36), status VARCHAR(30) DEFAULT 'draft', total_amount DECIMAL(12,2) DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sales_orders (id VARCHAR(36) PRIMARY KEY, so_number VARCHAR(50) UNIQUE, customer_id VARCHAR(36), status VARCHAR(30) DEFAULT 'draft', total_amount DECIMAL(12,2) DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invoices (id VARCHAR(36) PRIMARY KEY, invoice_number VARCHAR(50) UNIQUE, customer_id VARCHAR(36), invoice_date DATE, status VARCHAR(30) DEFAULT 'draft', total_amount DECIMAL(12,2) DEFAULT 0, balance_amount DECIMAL(12,2) DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS delivery_challans (id VARCHAR(36) PRIMARY KEY, challan_number VARCHAR(50) UNIQUE, customer_id VARCHAR(36), challan_date DATE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS employees (id VARCHAR(36) PRIMARY KEY, employee_code VARCHAR(50) UNIQUE, name VARCHAR(200), department_id INT, basic_salary DECIMAL(10,2) DEFAULT 0, is_active TINYINT(1) DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attendance (id VARCHAR(36) PRIMARY KEY, employee_id VARCHAR(36), attendance_date DATE, status VARCHAR(20) DEFAULT 'present', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY unique_att(employee_id,attendance_date));
CREATE TABLE IF NOT EXISTS leave_requests (id VARCHAR(36) PRIMARY KEY, employee_id VARCHAR(36), from_date DATE, to_date DATE, days INT, status VARCHAR(20) DEFAULT 'pending', created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS password_reset_tokens (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, token_hash CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX idx_reset_token(token_hash));
CREATE TABLE IF NOT EXISTS payroll_runs (id VARCHAR(36) PRIMARY KEY, period VARCHAR(20) NOT NULL, status VARCHAR(20) DEFAULT 'draft', total_amount DECIMAL(14,2) DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS gate_pass (id VARCHAR(36) PRIMARY KEY, pass_number VARCHAR(50) UNIQUE, pass_type VARCHAR(20), item_id VARCHAR(36), warehouse_id VARCHAR(36), quantity DECIMAL(10,3) DEFAULT 0, status VARCHAR(20) DEFAULT 'open', created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
